function EULER_CHAR(n, h):
    s <- 0
    for p in 0..n:
        for q in 0..n:
            s <- s + (-1)^(p+q) * h(p, q)
    return s

function VERIFY_MIRROR_LAW(n, h):
    mh(p, q) := h(n - p, q)
    return EULER_CHAR(n, mh) == (-1)^n * EULER_CHAR(n, h)

