    lhs, rhs = fe_lhs(q, n, T), fe_rhs(q, n, T)
    return abs(lhs - rhs) <= tol * (1 + abs(lhs))

if __name__ == "__main__":
    for q in (2, 3, 5):
        for n in range(6):
            for T in (Fraction(1, 7), Fraction(-3, 2), Fraction(4)):
                assert verify_functional_equation(q, n, float(T))
    print("Weil functional equation verified.")

